action-title:
import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

function App() {
    var period = React.useState(false), shown = React.useState(true), restore = React.useRef(null);
    React.useEffect(function () {
        if (!shown[0] && restore.current)
            restore.current.querySelector('button').focus();
    }, [shown[0]]);
    return <div className="dsbanner-example">
    <style>{exampleStyles}</style>
    <div className={"demo-stack"}>
    <p>
    {period[0] ? 'Период отчёта: последние 7 дней.' : 'Период отчёта: последний год.'}
    </p>
    {period[0] ? <S.DsBanner headingLevel={'h4'} announcement={'polite'} tone={'info'} title={'Доступны данные за весь выбранный период'}>
    {'Хранение данных — 90 дней.'}
    </S.DsBanner> : <S.DsBanner headingLevel={'h4'} announcement={'polite'} tone={'warning'} title={'Период отчёта длиннее срока хранения'} actions={<S.DsButton size={'sm'} tone={'secondary'} onClick={function () { period[1](true); }}>
    {'Выбрать последние 7 дней'}
    </S.DsButton>}>
    {'Часть данных за последний год уже недоступна. Выберите более короткий период.'}
    </S.DsBanner>}
    {period[0] ? <div className={'actions'}>
    <S.DsButton size={'sm'} tone={'ghost'} onClick={function () { period[1](false); }}>
    {'Вернуть исходный период'}
    </S.DsButton>
    </div> : null}
    </div>
    </div>;
}

const exampleStyles = ".dsbanner-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dsbanner-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dsbanner-example p{margin:0}\n.dsbanner-example .actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}";

export { App as Example };

