retry-title:
import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

function RetryExample() {
    var phase = React.useState('error'), attempts = React.useState(0), timer = React.useRef(null);
    React.useEffect(function () { return function () { clearTimeout(timer.current); }; }, []);
    function retry() {
        if (phase[0] === 'loading')
            return;
        if (phase[0] === 'ready') {
            phase[1]('error');
            attempts[1](0);
            return;
        }
        phase[1]('loading');
        attempts[1](function (count) { return count + 1; });
        timer.current = setTimeout(function () { phase[1]('ready'); }, 1200);
    }
    var title = phase[0] === 'ready' ? 'Соединение восстановлено' : phase[0] === 'loading' ? 'Загружаем отчёт' : 'Не удалось загрузить отчёт';
    var body = phase[0] === 'ready' ? 'Данные отчёта снова доступны.' : phase[0] === 'loading' ? 'Повторный запрос выполняется. Дождитесь ответа.' : 'Временно нет связи с сервисом отчётов. Повторите запрос; выбранный период сохранён.';
    return <div className={"demo-stack"}>
    <S.DsBanner headingLevel={'h4'} tone={phase[0] === 'error' ? 'danger' : phase[0] === 'ready' ? 'success' : 'info'} announcement={'polite'} title={title} actions={<S.DsButton tone={'secondary'} size={'sm'} loading={phase[0] === 'loading'} onClick={retry}>
    {phase[0] === 'ready' ? 'Снова показать ошибку' : 'Повторить запрос'}
    </S.DsButton>}>
    {body}
    </S.DsBanner>
    <p>
    {'Попыток: ' + attempts[0]}
    </p>
    </div>;
}
function App() {
    var shown = React.useState(true), restore = React.useRef(null);
    React.useEffect(function () {
        if (!shown[0] && restore.current)
            restore.current.querySelector('button').focus();
    }, [shown[0]]);
    return <div className="dsbanner-example">
    <style>{exampleStyles}</style>
    <RetryExample />
    </div>;
}

const exampleStyles = ".dsbanner-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dsbanner-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dsbanner-example p{margin:0}\n";

export { App as Example };

two-actions-title:
import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

function TwoActionsExample() {
    var short = React.useState(false), help = React.useState(false), helpRef = React.useRef(null), linkRef = React.useRef(null);
    React.useEffect(function () {
        if (help[0] && helpRef.current)
            helpRef.current.focus();
    }, [help[0]]);
    return <div className={"demo-stack"}>
    <S.DsBanner headingLevel={'h4'} tone={short[0] ? 'info' : 'warning'} announcement={'polite'} title={short[0] ? 'Период соответствует сроку хранения' : 'В отчёте за год будут доступны не все поездки'} actions={[
            <S.DsButton key={'period'} tone={'secondary'} size={'sm'} onClick={function () { short[1](!short[0]); }}>
        {short[0] ? 'Вернуть исходный период' : 'Выбрать 30 дней'}
        </S.DsButton>,
            <a key={'help'} className={'text-link'} href={'#storage-help'} ref={linkRef} onClick={function (event) { event.preventDefault(); help[1](true); }}>
        {'О сроке хранения данных'}
        </a>
        ]}>
    {short[0] ? 'Для отчёта выбраны последние 30 дней. Все поездки этого периода доступны.' : 'История поездок хранится 90 дней. За более ранние даты подробные маршруты уже недоступны, поэтому итоговые показатели за год будут неполными. Выберите последние 30 дней или узнайте, какие данные сохраняются дольше.'}
    </S.DsBanner>
    <div id={'storage-help'} className={'help'} hidden={!help[0]} tabIndex={-1} ref={helpRef}>
    <h4>
    {'Срок хранения данных'}
    </h4>
    <p>
    {'Подробная история поездок хранится 90 дней. Сохранённые выгрузки доступны отдельно; изменение периода не восстанавливает удалённые маршруты.'}
    </p>
    <S.DsButton tone={'ghost'} size={'sm'} onClick={function () { help[1](false); linkRef.current.focus(); }}>
    {'Закрыть пояснение'}
    </S.DsButton>
    </div>
    </div>;
}
function App() {
    var shown = React.useState(true), restore = React.useRef(null);
    React.useEffect(function () {
        if (!shown[0] && restore.current)
            restore.current.querySelector('button').focus();
    }, [shown[0]]);
    return <div className="dsbanner-example">
    <style>{exampleStyles}</style>
    <TwoActionsExample />
    </div>;
}

